  const dict = new Map(rows.map(([en, variants]) => [en, variants[locale] || en]));
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  for (const node of nodes) {
    const parent = node.parentElement;
    if (!parent || ["SCRIPT", "STYLE"].includes(parent.tagName)) continue;
    const value = node.nodeValue || "";
    const key = value.trim();
    const translated = dict.get(key);
    if (translated && translated !== key) node.nodeValue = value.replace(key, translated);
  }

  document.documentElement.lang = locale;
  root.dataset.hcHubLocale = locale;
  try { window.localStorage.setItem("hermes-connect-language", locale); } catch {}

  const languageNames = {en:"English",ru:"Русский",uk:"Українська",es:"Español",it:"Italiano",fr:"Français"};
  const contentLabels = {
    en:"Content language: English",ru:"Язык контента: русский",uk:"Мова контенту: українська",
    es:"Idioma del contenido: español",it:"Lingua dei contenuti: italiano",fr:"Langue du contenu : français"
  };
  const productContext = document.querySelector("[data-hc-product-context]");
  const contentLanguage = productContext?.querySelector(".hc-content-language");
  if (contentLanguage) contentLanguage.textContent = contentLabels[locale];
  const languageLabel = productContext?.querySelector(".hc-language-menu strong");
  if (languageLabel) languageLabel.textContent = languageNames[locale];

  const aria = {
    en:["Current Hermes Connect product status","Hermes Connect product preview"],
    ru:["Текущий статус продукта Hermes Connect","Превью продукта Hermes Connect"],
    uk:["Поточний статус продукту Hermes Connect","Прев’ю продукту Hermes Connect"],
    es:["Estado actual del producto Hermes Connect","Vista previa del producto Hermes Connect"],
    it:["Stato attuale del prodotto Hermes Connect","Anteprima del prodotto Hermes Connect"],
    fr:["État actuel du produit Hermes Connect","Aperçu du produit Hermes Connect"]
  }[locale];
  root.querySelector('[aria-label="Current Hermes Connect product status"],[aria-label="Текущий статус продукта Hermes Connect"]')?.setAttribute("aria-label", aria[0]);
  root.querySelector('[aria-label="Hermes Connect product preview"],[aria-label="Превью продукта Hermes Connect"]')?.setAttribute("aria-label", aria[1]);

  const titles = {
    en:"Hermes Connect | AI Operating System for Business",
    ru:"Hermes Connect | AI-операционная система для бизнеса",
    uk:"Hermes Connect | AI-операційна система для бізнесу",
    es:"Hermes Connect | Sistema operativo de IA para empresas",
    it:"Hermes Connect | Sistema operativo AI per le aziende",
    fr:"Hermes Connect | Système d’exploitation IA pour les entreprises"
  };
  const descriptions = {
    en:"Run your business with AI. Hermes Connect adapts one operating system to different business workflows, with Repair Shops as the current public live vertical and private Academy business-owner, Academy learner, and Beauty workspaces with bounded scopes.",
    ru:"Управляйте бизнесом с AI. Hermes Connect адаптирует единую операционную систему под разные бизнес-процессы; СТО — текущее публичное рабочее направление, Academy и Beauty — приватные пространства с ограниченным подтверждённым набором функций.",
    uk:"Керуйте бізнесом з AI. Hermes Connect адаптує єдину операційну систему до різних бізнес-процесів; СТО — поточний публічний робочий напрям, Academy і Beauty — приватні простори з обмеженим підтвердженим набором функцій.",
    es:"Gestiona tu empresa con IA. Hermes Connect adapta un sistema operativo a distintos flujos de negocio; Talleres es el vertical público activo y Academy y Beauty son espacios privados con alcance limitado.",
    it:"Gestisci la tua azienda con l’AI. Hermes Connect adatta un unico sistema operativo a diversi flussi aziendali; Officine è il verticale pubblico attivo e Academy e Beauty sono spazi privati con ambito limitato.",
    fr:"Pilotez votre entreprise avec l’IA. Hermes Connect adapte un système d’exploitation à différents flux métier ; Ateliers est le vertical public actif et Academy et Beauty sont des espaces privés à périmètre limité."
  };
  document.title = titles[locale];
  document.querySelector('meta[name="description"]')?.setAttribute("content", descriptions[locale]);

  document.querySelectorAll("a[href]").forEach((link) => {
    if (!(link instanceof HTMLAnchorElement)) return;
    const raw = link.getAttribute("href") || "";
    if (!raw || raw.startsWith("mailto:") || raw.startsWith("tel:") || raw.startsWith("javascript:") || raw.startsWith("#")) return;
    const url = new URL(raw, window.location.href);
    if (url.origin !== window.location.origin) return;
    if (url.pathname.startsWith("/services/hermes-connect/") || url.pathname.startsWith("/load-board/")) {
      if (locale === "en") url.searchParams.delete("lang");
      else url.searchParams.set("lang", locale);
      link.setAttribute("href", `${url.pathname}${url.search}${url.hash}`);
    }
  });
